parameters.jsCode:
// Extract the analysis from Anthropic response
const response = $input.item.json;
let analysisOutput;

// Handle different response structures
if (response.content && Array.isArray(response.content)) {
  const textContent = response.content.find(item => item.type === 'text');
  if (textContent && textContent.text) {
    analysisOutput = textContent.text;
  }
} else if (response.completion) {
  analysisOutput = response.completion;
} else if (typeof response === 'string') {
  analysisOutput = response;
} else {
  analysisOutput = JSON.stringify(response);
}

return {
  json: {
    performance_analysis: analysisOutput,
    timestamp: new Date().toISOString(),
    original_metrics: $('Set Performance Variables').item.json
  }
};
